/* ------------------------------------------------------------------
   i18n runtime
   - picks: ?lang=xx  >  saved choice  >  browser languages  >  English
   - elements: data-i18n (text), data-i18n-ph (placeholder),
               data-i18n-aria (aria-label)
   ------------------------------------------------------------------ */
(function(){
  const STORE = 'gsf-lang';
  const ALIAS = { nb:'no', nn:'no', cnr:'sr', sh:'sr', mo:'ro', gsw:'de', fy:'nl', eu:'es', gl:'es', br:'fr', co:'fr', cy:'en', gd:'en' };
  const has = c => !!window.I18N[c];
  const norm = tag => { if (!tag) return null; const p = String(tag).toLowerCase().split(/[-_]/)[0]; const c = ALIAS[p] || p; return has(c) ? c : null; };

  function detect(){
    try { const q = new URLSearchParams(location.search).get('lang'); if (norm(q)) return norm(q); } catch(e){}
    try { const s = localStorage.getItem(STORE); if (norm(s)) return norm(s); } catch(e){}
    const list = (navigator.languages && navigator.languages.length) ? navigator.languages : [navigator.language];
    for (const l of list){ const c = norm(l); if (c) return c; }
    return 'en';
  }

  const I = window.I18n = {
    lang: 'en',
    listeners: [],
    t(key, vars){
      let s = (window.I18N[I.lang] && window.I18N[I.lang][key]) ?? window.I18N.en[key] ?? key;
      if (vars) for (const k in vars) s = s.split('{'+k+'}').join(vars[k]);
      return s;
    },
    num(n){ try { return new Intl.NumberFormat(I.lang === 'no' ? 'nb' : I.lang).format(n); } catch(e){ return String(n); } },
    apply(root = document){
      root.querySelectorAll('[data-i18n]').forEach(el => {
        const txt = I.t(el.dataset.i18n);
        if (el.hasAttribute('data-split') && el.dataset.splitDone){
          // headings already split into animated words: rebuild the word spans
          el.innerHTML = txt.split(/\s+/).map(w => `<span class="w"><span>${w}</span></span>`).join(' ');
        } else el.textContent = txt;
      });
      root.querySelectorAll('[data-i18n-ph]').forEach(el => el.setAttribute('placeholder', I.t(el.dataset.i18nPh)));
      root.querySelectorAll('[data-i18n-aria]').forEach(el => el.setAttribute('aria-label', I.t(el.dataset.i18nAria)));
      document.documentElement.lang = I.lang;
      document.title = I.t('title');
      const md = document.querySelector('meta[name="description"]'); if (md) md.setAttribute('content', I.t('desc'));
    },
    set(code, save){
      const c = norm(code) || 'en';
      I.lang = c;
      if (save){ try { localStorage.setItem(STORE, c); } catch(e){} }
      I.apply();
      document.querySelectorAll('.lang-select').forEach(s => { s.value = c; });
      I.listeners.forEach(f => f(c));
    },
    onChange(f){ I.listeners.push(f); },
    init(){
      document.querySelectorAll('.lang-select').forEach(sel => {
        sel.innerHTML = window.I18N_LANGS.filter(([c]) => has(c)).map(([c,n]) => `<option value="${c}" lang="${c}">${n}</option>`).join('');
        sel.addEventListener('change', () => I.set(sel.value, true));
      });
      I.set(detect(), false);
    }
  };
})();
